"""Bounded p004 construction exploration. No background process, no file output.

Uses independent auxiliary sets only. Strict slot models forbid point duplicates.
Optional-deletion CP-SAT uses the uncompressed actual X-point model, with a
fixed threshold 134754. UNSAT/INFEASIBLE conclusions apply only to tested inputs.
"""
import argparse
import base64
import importlib.util
import json
from pathlib import Path
import random
import time
import zlib
from collections import Counter
import model as m

def _repo_root():
    import os
    for c in [os.environ.get('FEW_SHOTS_REPO'),str(Path.cwd()),'/Users/shiny/.sclaw/workspace/few-shots']:
        if c and (Path(c)/'problems/p004-shannon-capacity-c7'/'verify'/'verify.py').exists():return Path(c)
    raise SystemExit('set FEW_SHOTS_REPO to a few-shots clone containing problems/p004-shannon-capacity-c7')
ROOT=_repo_root()/'problems/p004-shannon-capacity-c7'
spec=importlib.util.spec_from_file_location('p004_official_verifier',ROOT/'verify/verify.py')
verifier=importlib.util.module_from_spec(spec);spec.loader.exec_module(verifier)

def verify(problem,full,label):
    C=problem.points(full)
    pts=[''.join(map(str,m.DIGITS[x//m.HALF]+m.DIGITS[x%m.HALF])) for x in sorted(C)]
    verdict=verifier.verify_bytes(json.dumps({'points':pts}).encode(),verifier.load_config())
    print('OFFICIAL_VERIFY',json.dumps({'label':label,'verdict':verdict},ensure_ascii=False),flush=True)
    if not verdict['valid']:raise RuntimeError('candidate failed official verifier')
    if int(verdict['score'])>=134754:
        witness={'baseR':problem.baseR,'pairs':problem.pairs,'X':problem.X,'full_assignment':full}
        blob=base64.b64encode(zlib.compress(json.dumps(witness,separators=(',',':')).encode(),9)).decode()
        print('VERIFIED_CONSTRUCTION_ZLIB_BASE64',blob,flush=True)
        return True
    return False

def optional_test(pairs,X,baseR,label,seconds):
    from ortools.sat.python import cp_model
    problem=m.StripModel(pairs,X,baseR=baseR,compress=False)
    allowance=problem.raw_size-134754
    if allowance<0:return 'BELOW_TARGET'
    cp=cp_model.CpModel();choice=[cp.NewBoolVar('c%d'%i) for i in range(2*problem.nvars)]
    for v in range(problem.nvars):cp.Add(choice[2*v]+choice[2*v+1]<=1)
    for u,a,v,b in problem.ts.forbidden:cp.AddBoolOr([choice[2*u+a].Not(),choice[2*v+b].Not()])
    cp.Add(sum(choice)>=problem.nvars-allowance)
    solver=cp_model.CpSolver();solver.parameters.max_time_in_seconds=seconds
    solver.parameters.num_search_workers=4;solver.parameters.random_seed=771001
    t=time.monotonic();status=solver.Solve(cp);name=solver.StatusName(status)
    print('OPTIONAL_CASE',json.dumps({'label':label,'status':name,'allowed_omissions':allowance,'active_slots':problem.nvars,'seconds':round(time.monotonic()-t,3)},ensure_ascii=False),flush=True)
    if status==cp_model.MODEL_INVALID:raise RuntimeError('invalid CP-SAT model')
    if status in (cp_model.OPTIMAL,cp_model.FEASIBLE):
        active=[0 if solver.Value(choice[2*v]) else (1 if solver.Value(choice[2*v+1]) else None) for v in range(problem.nvars)]
        full=problem.expand(active)
        if not verify(problem,full,label):raise RuntimeError('threshold constraint did not produce target size')
        return 'VERIFIED_BREAKTHROUGH'
    return name

def private_pairs(R):
    Rm=sum(1<<m.enc5(x) for x in R);pairs=[]
    for q in range(m.HALF):
        if (Rm>>q)&1:continue
        b=m.N[q]&Rm
        if b.bit_count()==1:pairs.append((m.DIGITS[b.bit_length()-1],m.DIGITS[q]))
    return pairs

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--seconds',type=float,default=60)
    ap.add_argument('--trials',type=int,default=10000);ap.add_argument('--cp-seconds',type=float,default=3)
    ap.add_argument('--cp-cases',type=int,default=8);ap.add_argument('--seed',type=int,default=20261031)
    a=ap.parse_args()
    if not 0<a.seconds<=180 or not 0<a.cp_seconds<=15 or not 0<=a.cp_cases<=20:raise ValueError('budget out of range')
    X0=[m.tr(x) for x in m.Rlist];X0[267]=(1,5,6,3,5)
    variant_counts=Counter()
    # New fixed cases: allow <=16 omissions for R1/R2, not just full 2-SAT.
    for name,old,new in [('R1',(6,0,6,4,5),(6,1,6,5,5)),('R2',(6,4,5,3,2),(6,5,5,3,1))]:
        R=[new if x==old else x for x in m.Rlist];pairs=private_pairs(R)
        if len(pairs)!=9:raise RuntimeError('unexpected private-pair count')
        raw=[m.tr(x) for x in R];patch=[(1,5,6,3,5) if x==(2,4,6,3,5) else x for x in raw]
        for label,X in [('X0',X0),('tr(R)',raw),('tr(R)+patch',patch)]:
            result=optional_test(pairs,X,R,name+':'+label,a.cp_seconds);variant_counts[result]+=1
            if result=='VERIFIED_BREAKTHROUGH':return
    print('VARIANT_OPTIONAL_SUMMARY',json.dumps(dict(variant_counts)),flush=True)
    candidates=m.natural_candidates();assert len(candidates)==50
    rng=random.Random(a.seed);started=time.monotonic();deadline=started+a.seconds
    done=0;transform_count=0;cached_count=0;strict_sat=0;intersection_cases=0;max_variables=0
    seen=[set() for _ in candidates];nearby=[]
    while done<a.trials and time.monotonic()<deadline:
        perm=list(range(5));rng.shuffle(perm);sign=[rng.choice((-1,1)) for _ in range(5)];shift=[rng.randrange(7) for _ in range(5)]
        source=m.Rlist if transform_count%2==0 else X0
        X=[tuple((sign[i]*p[perm[i]]+shift[i])%7 for i in range(5)) for p in source]
        transform_count+=1
        assert m.independent5(X)
        order=list(range(len(candidates)));rng.shuffle(order)
        for idx in order:
            if done>=a.trials or time.monotonic()>=deadline:break
            pairs=m.PAIRS8+[candidates[idx]]
            p=m.StripModel(pairs,X);key=tuple(p.patterns)
            if key in seen[idx]:cached_count+=1;continue
            seen[idx].add(key);done+=1;max_variables=max(max_variables,p.nvars)
            intersection_cases+=bool(set(p.X)&set(p.elements))
            sol=p.solve()
            if sol is not None:
                strict_sat+=1
                if verify(p,sol,'automorphism_%d_pair_%d'%(transform_count,idx)):return
            # This is only a heuristic ranking; contradiction count is NOT a deletion bound.
            rank=(len(p.ts.contradictory_variables),len(p.ts.forbidden),p.ng)
            label='automorphism_%d_pair_%d'%(transform_count,idx)
            nearby.append((rank,label,idx,X))
            nearby.sort(key=lambda r:(r[0],r[1]));del nearby[a.cp_cases:]
    print('AUTOMORPHISM_SUMMARY',json.dumps({'transforms_generated':transform_count,'distinct_models_solved':done,'duplicate_contact_models_skipped':cached_count,'models_with_X_endpoint_overlap':intersection_cases,'strict_SAT':strict_sat,'max_variables':max_variables,'seconds':round(time.monotonic()-started,3),'exhaustive':False}),flush=True)
    cp_counts=Counter()
    for rank,label,idx,X in nearby:
        result=optional_test(m.PAIRS8+[candidates[idx]],X,m.Rlist,label,a.cp_seconds)
        cp_counts[result]+=1
        if result=='VERIFIED_BREAKTHROUGH':return
    print('AUTOMORPHISM_OPTIONAL_SUMMARY',json.dumps({'tested':len(nearby),'statuses':dict(cp_counts),'ranking_is_heuristic':True}),flush=True)
    print('SEARCH_RESULT no_verified_improvement_in_this_bounded_run',flush=True)

