# END_ASYM_CHECKPOINT

def asymmetric_patch_search(seconds=90,max_new=40,cp_seconds=2.0,max_expansions=2000):
    """Continue one-sided auxiliary-set search. Returns a data-only checkpoint.

    Previous bilateral 40-class experiment is a different parameter family;
    those models are NOT re-solved here. The symmetric root has known optimum
    17, established by the prior audited model. All new classes are evaluated
    with separate horizontal and vertical signatures and multiplicities.
    """
    import heapq,hashlib,math
    from ortools.sat.python import cp_model
    if not 0<seconds<=180 or not 0<cp_seconds<=10 or not 0<max_new<=150:raise ValueError('invalid patch budget')
    R=[(6,5,5,3,1) if x==(6,4,5,3,2) else x for x in m.Rlist]
    pairs=private_pairs(R)
    if len(pairs)!=9:raise RuntimeError('unexpected pair count')
    X=[m.tr(x) for x in R];X=[(1,5,6,3,5) if x==(2,4,6,3,5) else x for x in X]
    rootmask=sum(1<<m.enc5(x) for x in X)
    fixed=[m.enc5(x) for x in X]
    endpoints=[m.enc5(x) for pair in pairs for x in pair]
    signatures=[sum(1<<j for j,e in enumerate(endpoints) if (m.N[e]>>x)&1) for x in range(m.HALF)]
    def signature_key(mask):return tuple(sorted(Counter(signatures[x] for x in m.bits(mask) if signatures[x]).items()))
    def pack(mask):return {'remove':list(m.bits(rootmask&~mask)),'add':list(m.bits(mask&~rootmask))}
    def unpack(delta):
        removed=sum(1<<x for x in delta['remove']);added=sum(1<<x for x in delta['add'])
        if removed&~rootmask or added&rootmask:raise ValueError('invalid checkpoint delta')
        mask=(rootmask&~removed)|added
        if mask.bit_count()!=367:raise ValueError('checkpoint cardinality mismatch')
        return mask
    instance=hashlib.sha256(json.dumps({'R':R,'pairs':pairs,'X':X},separators=(',',':')).encode()).hexdigest()
    history=[];cache={signature_key(rootmask):{'status':'PREVIOUS_OPTIMAL','holes':17,'lower_bound':17}}
    seen={rootmask};expanded_masks=set();serial=1;frontier=[(17,0,0,rootmask)]
    if ASYM_CHECKPOINT is not None:
        previous=ASYM_CHECKPOINT
        if previous.get('version')!=1 or previous.get('instance')!=instance:raise ValueError('checkpoint instance mismatch')
        history=list(previous['history'])
        for item in history:
            state=unpack(item['state']);key=signature_key(state)
            if hashlib.sha256(repr(key).encode()).hexdigest()!=item['class_digest']:raise ValueError('checkpoint class mismatch')
            cache[key]=item
        seen={unpack(d) for d in previous['seen']};expanded_masks={unpack(d) for d in previous['expanded']}
        frontier=[(x['priority'],x['depth'],x['serial'],unpack(x['state'])) for x in previous['frontier']]
        heapq.heapify(frontier);serial=previous['next_serial']
    initial_history=len(history);initial_expanded=len(expanded_masks)
    new_status=Counter();started=time.monotonic();deadline=started+seconds;new_models=0;cache_hits=0
    verified_sample=None;witness=None;max_depth=0
    print('ASYMMETRIC_RESUME',json.dumps({'cached_nonroot_classes':len(history),'pending_states':len(frontier),'previously_expanded_states':len(expanded_masks),'bilateral_classes_not_repeated':40}),flush=True)
    while frontier and new_models<max_new and len(expanded_masks)-initial_expanded<max_expansions and time.monotonic()<deadline:
        priority,depth,tag,M=heapq.heappop(frontier)
        if M in expanded_masks:continue
        max_depth=max(max_depth,depth)
        key=signature_key(M);cached=cache.get(key)
        if cached is None:
            XH=list(m.bits(M))
            p=m.AsymmetricStripModel(pairs,XH,fixed,baseR=R,compress=True)
            if p.raw_size!=134770:raise RuntimeError('unexpected raw construction size')
            cp=cp_model.CpModel();ch=[cp.NewBoolVar('c%d'%i) for i in range(2*p.nvars)]
            for i in range(p.nvars):cp.Add(ch[2*i]+ch[2*i+1]<=1)
            for u,a,v,b in p.ts.forbidden:cp.AddBoolOr([ch[2*u+a].Not(),ch[2*v+b].Not()])
            kept=sum(p.weights[i]*(ch[2*i]+ch[2*i+1]) for i in range(p.nvars));cp.Maximize(kept)
            # NO H>=V constraint: the two auxiliary sets now differ.
            target=p.active_slots-16
            class Goal(cp_model.CpSolverSolutionCallback):
                def on_solution_callback(self):
                    if self.ObjectiveValue()>=target:self.StopSearch()
            solver=cp_model.CpSolver();solver.parameters.num_search_workers=4
            solver.parameters.max_time_in_seconds=min(cp_seconds,max(.05,deadline-time.monotonic()))
            solver.parameters.random_seed=271828+initial_history+new_models
            st=solver.Solve(cp,Goal());name=solver.StatusName(st);new_models+=1;new_status[name]+=1
            if st==cp_model.MODEL_INVALID:raise RuntimeError('invalid asymmetric optimization model')
            feasible=st in (cp_model.OPTIMAL,cp_model.FEASIBLE)
            holes=p.active_slots-round(solver.ObjectiveValue()) if feasible else None
            lb=max(0,p.active_slots-math.floor(solver.BestObjectiveBound()+1e-6)) if feasible else None
            if feasible and not lb<=holes:raise RuntimeError('invalid objective bound')
            cached={'class_digest':hashlib.sha256(repr(key).encode()).hexdigest(),'state':pack(M),'depth':depth,'status':name,'holes':holes,'lower_bound':lb}
            history.append(cached);cache[key]=cached
            print('ASYMMETRIC_CLASS',json.dumps({'number':len(history),'depth':depth,'status':name,'feasible_omissions':holes,'omission_lower_bound':lb,'state':pack(M)}),flush=True)
            if feasible and holes<=17 and (verified_sample is None or holes<=16):
                active=[0 if solver.Value(ch[2*i]) else (1 if solver.Value(ch[2*i+1]) else None) for i in range(p.nvars)]
                full=p.expand(active);C=p.points(full)
                pts=[''.join(map(str,m.DIGITS[x//m.HALF]+m.DIGITS[x%m.HALF])) for x in sorted(C)]
                verdict=verifier.verify_bytes(json.dumps({'points':pts}).encode(),verifier.load_config())
                if not verdict['valid']:raise RuntimeError('asymmetric candidate failed official verifier')
                if int(verdict['score'])!=p.raw_size-holes:raise RuntimeError('objective differs from verified size')
                verified_sample={'class':len(history),'verdict':verdict}
                print('OFFICIAL_ASYMMETRIC_VERIFY',json.dumps(verified_sample,ensure_ascii=False),flush=True)
                if int(verdict['score'])>=134754:
                    witness={'baseR':p.baseR,'pairs':p.pairs,'XH':p.XH,'XV':p.XV,'assignment':full}
                    blob=base64.b64encode(zlib.compress(json.dumps(witness,separators=(',',':')).encode(),9)).decode()
                    print('VERIFIED_ASYMMETRIC_CONSTRUCTION_ZLIB_BASE64',blob,flush=True)
                    break
        else:cache_hits+=1
        actual_priority=cached.get('holes')
        if actual_priority is None:actual_priority=cached.get('lower_bound') or 17
        if actual_priority>priority and frontier and frontier[0][0]<actual_priority:
            heapq.heappush(frontier,(actual_priority,depth,tag,M));continue
        # Exhaustive one-point replacements of THIS auxiliary set, not of all X.
        for q in range(m.HALF):
            if (M>>q)&1:continue
            b=m.N[q]&M
            if not b or b&(b-1):continue
            child=(M^b)|(1<<q)
            if child in seen:continue
            seen.add(child);info=cache.get(signature_key(child))
            child_priority=(info.get('holes') if info else None)
            if child_priority is None:child_priority=actual_priority
            heapq.heappush(frontier,(child_priority,depth+1,serial,child));serial+=1
        expanded_masks.add(M)
    unresolved=sum(item.get('lower_bound') is None or item['lower_bound']<17 for item in history)
    summary={'new_models':new_models,'statuses':dict(new_status),'cached_class_uses':cache_hits,'expanded_states_this_run':len(expanded_masks)-initial_expanded,'expanded_states_total':len(expanded_masks),'seen_states':len(seen),'pending_states':len(frontier),'max_popped_depth_this_run':max_depth,'smallest_feasible_omissions':min([17]+[i['holes'] for i in history if i['holes'] is not None]),'unresolved_target_classes':unresolved,'seconds':round(time.monotonic()-started,3),'exhaustive':False,'verified_improvement':witness is not None}
    print('ASYMMETRIC_PATCH_RESULT',json.dumps(summary),flush=True)
    return {'version':1,'instance':instance,'history':history,'seen':[pack(M) for M in sorted(seen)],'expanded':[pack(M) for M in sorted(expanded_masks)],'frontier':[{'priority':p,'depth':d,'serial':t,'state':pack(M)} for p,d,t,M in frontier],'next_serial':serial,'last_summary':summary,'verified_sample':verified_sample,'witness':witness}

